  const WH = /^https:\/\/(?:discord|discordapp)\.com\/api\/webhooks\//;
  function post(url, body) {
    return new Promise(res => {
      if (typeof GM_xmlhttpRequest === 'function') {
        GM_xmlhttpRequest({
          method: 'POST', url, data: body, headers: { 'Content-Type': 'application/json' },
          onload: r => res({ ok: r.status >= 200 && r.status < 300, status: r.status }),
          onerror: () => res({ ok: false, status: 'error' }),
          ontimeout: () => res({ ok: false, status: 'timeout' })
        });
      } else {
        fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body })
          .then(r => res({ ok: r.ok, status: r.status })).catch(() => res({ ok: false, status: 'blocked' }));
      }
    });
  }
  async function hook(embed) {
    if (!WH.test(cfg.hook)) return { ok: false, status: 'URL salah' };
    const payload = { username: (cfg.hookName || 'FS Fishing'), embeds: [Object.assign({ footer: { text: (cfg.hookName || 'FS Panel') }, timestamp: new Date().toISOString() }, embed)] };
    if (/^https:\/\/\S+$/.test(cfg.hookLogo || '')) payload.avatar_url = cfg.hookLogo;
    const body = JSON.stringify(payload);
    const r = await post(cfg.hook, body);
    if (!r.ok) logs.push('WEBHOOK gagal: ' + r.status);
    return r;
  }
