        for (let y = ya; y < yb; y++) for (let x = 0; x < W; x++) { const i = (y * W + x) * 4; cR[x] += d[i]; cG[x] += d[i + 1]; cB[x] += d[i + 2]; }
        const nr = yb - ya;
        for (let x = 0; x < W; x++) { cR[x] /= nr; cG[x] /= nr; cB[x] /= nr; }
        const hx2 = (r, g2, b2) => [r, g2, b2].map(v => Math.round(v).toString(16).padStart(2, '0')).join('');
        const sp = [];
