        for (let x = 0; x < W; x++) if (!mk[x]) { let e = x; while (e < W && !mk[e]) e++; if (x > 0 && e < W && mk[x - 1] && e - x <= gap) for (let k = x; k < e; k++) mk[k] = true; x = e; }
